//! Parity against three.js r186 `src/core`.
//!
//! Replays every case of `parity/core/core.json` (generated by
//! `parity/core/gen/generate.mjs` from the real three.js modules) and requires
//! `|got - expected| <= 1e-6 * max(1, |expected|)`, the tolerance of DECISIONS.md D2.
//!
//! Run with `cargo test -p wamr-core --test parity -- --nocapture` for the summary.

use serde_json::Value;
use std::collections::BTreeMap;
use wamr_core::*;
use wamr_math::{Euler, EulerOrder, Matrix3, Matrix4, Quaternion, Vector3};

const TOLERANCE: f64 = 1e-6;
const ORDERS: [EulerOrder; 6] =
    [EulerOrder::XYZ, EulerOrder::YXZ, EulerOrder::ZXY, EulerOrder::ZYX, EulerOrder::YZX, EulerOrder::XZY];

struct In<'a> {
    v: &'a [f64],
    i: usize,
}

impl In<'_> {
    fn d(&mut self) -> f64 {
        self.i += 1;
        self.v[self.i - 1]
    }
    fn s(&mut self) -> f32 {
        let x = self.d();
        assert!(x as f32 as f64 == x, "float input {x} is not an f32 value");
        x as f32
    }
    fn u(&mut self) -> usize {
        self.d() as usize
    }
    fn floats(&mut self, n: usize) -> Vec<f32> {
        (0..n).map(|_| self.s()).collect()
    }
    fn v3(&mut self) -> Vector3 {
        Vector3::new(self.s(), self.s(), self.s())
    }
    fn q(&mut self) -> Quaternion {
        Quaternion::new(self.s(), self.s(), self.s(), self.s())
    }
    fn m3(&mut self) -> Matrix3 {
        Matrix3 { elements: core::array::from_fn(|_| self.s()) }
    }
    fn m4(&mut self) -> Matrix4 {
        Matrix4 { elements: core::array::from_fn(|_| self.s()) }
    }
}

fn typed_array(kind: usize, len: usize) -> AttributeArray {
    match kind {
        0 => AttributeArray::Float32(vec![0.0; len]),
        1 => AttributeArray::Uint32(vec![0; len]),
        2 => AttributeArray::Uint16(vec![0; len]),
        3 => AttributeArray::Uint8(vec![0; len]),
        4 => AttributeArray::Int32(vec![0; len]),
        5 => AttributeArray::Int16(vec![0; len]),
        6 => AttributeArray::Int8(vec![0; len]),
        _ => AttributeArray::Uint8Clamped(vec![0; len]),
    }
}

fn raw(array: &AttributeArray) -> Vec<f64> {
    (0..array.len()).map(|i| array.get(i)).collect()
}

fn f32_attribute(values: Vec<f32>, item_size: usize) -> BufferAttribute {
    BufferAttribute::new(AttributeArray::Float32(values), item_size, false)
}

/// `[vertexCount, positions, uvs, indexCount, indices]`
fn mesh(r: &mut In) -> BufferGeometry {
    let n = r.u();
    let mut geometry = BufferGeometry::new();
    geometry.set_attribute("position", f32_attribute(r.floats(n * 3), 3));
    geometry.set_attribute("uv", f32_attribute(r.floats(n * 2), 2));
    let k = r.u();
    let indices: Vec<u32> = (0..k).map(|_| r.u() as u32).collect();
    if k > 0 {
        geometry.set_index_from_slice(&indices);
    }
    geometry
}

fn attribute_values(geometry: &BufferGeometry, name: &str) -> Vec<f64> {
    raw(&geometry.get_attribute(name).unwrap_or_else(|| panic!("no {name} attribute")).array)
}

fn bounds(geometry: &BufferGeometry, with_sphere: bool) -> Vec<f64> {
    let b = geometry.bounding_box.expect("bounding box");
    let mut out: Vec<f64> = b.min.to_array().iter().chain(&b.max.to_array()).map(|x| *x as f64).collect();
    if with_sphere {
        let s = geometry.bounding_sphere.expect("bounding sphere");
        out.extend(s.center.to_array().iter().map(|x| *x as f64));
        out.push(s.radius as f64);
    }
    out
}

fn transform_state(t: &Transform) -> Vec<f64> {
    let mut out = Vec::new();
    out.extend(t.position.to_array());
    out.extend(t.quaternion().to_array());
    out.extend(t.rotation().to_array());
    out.extend(t.scale.to_array());
    out.into_iter().map(|x: f32| x as f64).collect()
}

fn run(op: &str, r: &mut In) -> Option<Vec<f64>> {
    let mut out: Vec<f64> = Vec::new();

    match op {
        "Layers.script" => {
            let mut layers = Layers::new();
            for _ in 0..8 {
                let (code, layer) = (r.u(), r.u() as u32);
                match code {
                    0 => layers.set(layer),
                    1 => layers.enable(layer),
                    2 => layers.toggle(layer),
                    3 => layers.disable(layer),
                    4 => layers.enable_all(),
                    _ => layers.disable_all(),
                }
                out.push(layers.mask as f64);
            }
            let probe = r.u() as u32;
            let mut other = Layers::new();
            other.set(probe);
            out.push(layers.is_enabled(probe) as u8 as f64);
            out.push(layers.test(&other) as u8 as f64);
        }
        "BufferAttribute.access" => {
            let (kind, normalized) = (r.u(), r.u() == 1);
            let v = r.floats(5);
            let mut a = BufferAttribute::new(typed_array(kind, 8), 4, normalized);
            a.set_xyzw(1, v[0], v[1], v[2], v[3]);
            a.set_component(0, 2, v[4]);
            a.set_x(0, v[0]);
            out = raw(&a.array);
            for x in [a.get_x(1), a.get_y(1), a.get_z(1), a.get_w(1), a.get_component(0, 2), a.get_x(0)] {
                out.push(x as f64);
            }
        }
        "BufferAttribute.applyMatrix4" | "BufferAttribute.transformDirection" => {
            let n = r.u();
            let mut a = f32_attribute(r.floats(n * 3), 3);
            let m = r.m4();
            if op.ends_with("applyMatrix4") {
                a.apply_matrix4(&m);
            } else {
                a.transform_direction(&m);
            }
            out = raw(&a.array);
        }
        "BufferAttribute.applyNormalMatrix" | "BufferAttribute.applyMatrix3" | "BufferAttribute.applyMatrix3.uv" => {
            let n = r.u();
            let item_size = if op.ends_with(".uv") { 2 } else { 3 };
            let mut a = f32_attribute(r.floats(n * item_size), item_size);
            let m = r.m3();
            if op.ends_with("applyNormalMatrix") {
                a.apply_normal_matrix(&m);
            } else {
                a.apply_matrix3(&m);
            }
            out = raw(&a.array);
        }
        "BufferGeometry.bounds" => {
            let mut g = mesh(r);
            g.compute_bounding_box();
            g.compute_bounding_sphere();
            out = bounds(&g, true);
        }
        "BufferGeometry.computeVertexNormals" => {
            let mut g = mesh(r);
            g.compute_vertex_normals();
            out = attribute_values(&g, "normal");
        }
        "BufferGeometry.center" => {
            let mut g = mesh(r);
            g.center();
            out = attribute_values(&g, "position");
            out.extend(bounds(&g, false));
        }
        "BufferGeometry.applyMatrix4" => {
            let mut g = mesh(r);
            let m = r.m4();
            g.compute_vertex_normals();
            g.compute_bounding_box();
            g.compute_bounding_sphere();
            g.apply_matrix4(&m);
            out = attribute_values(&g, "position");
            out.extend(attribute_values(&g, "normal"));
            out.extend(bounds(&g, true));
        }
        "BufferGeometry.computeTangents" => {
            let mut g = mesh(r);
            g.compute_vertex_normals();
            g.compute_tangents();
            out = attribute_values(&g, "tangent");
        }
        "BufferGeometry.toNonIndexed" => {
            let flat = mesh(r).to_non_indexed();
            out = attribute_values(&flat, "position");
            out.extend(attribute_values(&flat, "uv"));
        }
        "BufferGeometry.setIndex" => {
            let max = r.u() as u32;
            let mut g = BufferGeometry::new();
            g.set_index_from_slice(&[0, max, 1]);
            let index = g.get_index().unwrap();
            out.push(matches!(index.array, AttributeArray::Uint32(_)) as u8 as f64);
            out.extend(raw(&index.array));
        }
        "Object3D.transform" => {
            let mut world = World::new();
            let object = world.create_object();
            let t = world.transform_mut(object).unwrap();

            t.position = r.v3();
            let (x, y, z, order) = (r.s(), r.s(), r.s(), ORDERS[r.u()]);
            t.set_rotation(Euler::new(x, y, z, order));
            t.scale = r.v3();
            let (has_pivot, pivot) = (r.u() == 1, r.v3());
            t.pivot = has_pivot.then_some(pivot);
            out.extend(transform_state(t));

            let (axis1, angle1) = (r.v3(), r.s());
            let (axis2, distance) = (r.v3(), r.s());
            let (axis3, angle3) = (r.v3(), r.s());
            let q = r.q();
            t.rotate_on_axis(&axis1, angle1);
            t.translate_on_axis(&axis2, distance);
            t.rotate_on_world_axis(&axis3, angle3);
            t.apply_quaternion(&q);
            t.update_matrix();
            out.extend(transform_state(t));
            out.extend(t.matrix.elements.iter().map(|e| *e as f64));

            t.apply_matrix4(&r.m4());
            out.extend(transform_state(t));
        }
        "Object3D.hierarchy" => {
            let count = r.u();
            let mut world = World::new();
            let objects: Vec<Entity> = (0..count).map(|_| world.create_object()).collect();

            for _ in 0..12 {
                let (code, a, b) = (r.u(), objects[r.u()], objects[r.u()]);
                match code {
                    0 => drop(world.add(a, b)),
                    1 => drop(world.remove(a, b)),
                    2 => world.remove_from_parent(a),
                    _ => world.clear(a),
                }
            }

            // entities were created in order, so the slot index is the fixture's object id
            let id = |e: Entity| e.index() as f64;
            let mut events = Vec::new();
            for event in world.drain_events() {
                match event {
                    CoreEvent::Added { entity } => events.extend([0.0, id(entity)]),
                    CoreEvent::Removed { entity } => events.extend([1.0, id(entity)]),
                    CoreEvent::ChildAdded { parent, child } => events.extend([2.0, id(parent), id(child)]),
                    CoreEvent::ChildRemoved { parent, child } => events.extend([3.0, id(parent), id(child)]),
                    other => panic!("unexpected event {other:?}"),
                }
            }
            out.push(events.len() as f64);
            out.extend(events);
            out.extend(objects.iter().map(|o| world.parent(*o).map_or(-1.0, id)));
            for o in &objects {
                out.push(world.children(*o).len() as f64);
                out.extend(world.children(*o).iter().map(|c| id(*c)));
            }
        }
        "Timer.updates" => {
            let mut timer = Timer::new(r.d());
            for _ in 0..6 {
                let (timescale, now) = (r.d(), r.d());
                if timescale >= 0.0 {
                    timer.set_timescale(timescale);
                }
                timer.update(now);
                out.push(timer.get_delta());
                out.push(timer.get_elapsed());
            }
        }
        _ => return None,
    }

    Some(out)
}

#[test]
fn core_matches_three_js() {
    let path = std::env::var("WAMR_CORE_PARITY").unwrap_or_else(|_| concat!(env!("CARGO_MANIFEST_DIR"), "/../../parity/core/core.json").to_string());
    let fixture: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let cases = fixture["cases"].as_array().unwrap();
    assert_eq!(fixture["meta"]["cases"].as_u64().unwrap() as usize, cases.len());

    let numbers = |v: &Value| -> Vec<f64> { v.as_array().unwrap().iter().map(|x| x.as_f64().expect("finite number")).collect() };

    // op -> (cases, values, largest scaled error)
    let mut summary: BTreeMap<String, (usize, usize, f64)> = BTreeMap::new();
    let mut failures = Vec::new();

    for (index, case) in cases.iter().enumerate() {
        let op = case["op"].as_str().unwrap();
        let (input, expected) = (numbers(&case["in"]), numbers(&case["out"]));

        let mut r = In { v: &input, i: 0 };
        let got = run(op, &mut r).unwrap_or_else(|| panic!("no Rust replay for op {op}"));
        assert_eq!(r.i, input.len(), "case {index} ({op}): replay read {} of {} inputs", r.i, input.len());
        assert_eq!(got.len(), expected.len(), "case {index} ({op}): output length");

        let entry = summary.entry(op.to_string()).or_default();
        entry.0 += 1;
        let mut ok = true;
        for (g, e) in got.iter().zip(&expected) {
            let scaled = (g - e).abs() / e.abs().max(1.0);
            entry.1 += 1;
            entry.2 = entry.2.max(scaled);
            ok &= scaled <= TOLERANCE;
        }

        if !ok && failures.len() < 8 {
            failures.push(format!("case {index} {op}\n    in:       {input:?}\n    expected: {expected:?}\n    got:      {got:?}"));
        }
    }

    for (op, (count, values, worst)) in &summary {
        println!("parity {op:<38} {count:>3} cases {values:>5} values  max |err|/max(1,|exp|) {worst:.3e}");
    }

    assert!(failures.is_empty(), "parity failures (first {}):\n{}", failures.len(), failures.join("\n"));
}
